<?php
declare(strict_types=1);

/**
 * install_standings_timeline_lite_v005.php
 *
 * VERSION: v001
 * LAST MODIFIED: 8/28/2026 1:56:47 am
 *
 * PURPOSE:
 * Final visual-alignment cleanup for standings_timeline_lite.php.
 *
 * MEASURED COMPARISON:
 * - Weekly Standings screenshot: yellow table-header band starts at y=156.
 * - Timeline Lite v004 screenshot: yellow table-header band starts at y=150.
 * - v005 moves Timeline Lite down by exactly 6px.
 *
 * CHANGES:
 * - 37px -> 43px top-controls bottom spacing.
 * - score/third columns centered to match Weekly Standings.
 * - seconds removed from displayed snapshot timestamps.
 *
 * SAFETY:
 * - exact SHA-256 baseline check for standings_timeline_lite.php v004
 * - backup before replacement
 * - complete-file replacement only
 * - verifies standings_timeline.php remains untouched
 * - rollback on write/postflight failure
 * - no weekly_standings.php change
 * - no DB, snapshot, scoring, LP/RD, audit, release-history, or timeline-engine changes
 */

date_default_timezone_set('America/New_York');

const LITE_BASE_SHA256 = 'ff1e82a7921e1efb7c06d3f0bc0892127fefa76a97c0adbbd45b55e966b35084';
const LITE_NEW_SHA256 = 'b4f7177cec9f2fbbf47a540ea60c183e67dd641aab86f20cf47731a072264ba1';
const TIMELINE_REFERENCE_SHA256 = 'b3671fae0998576b36055b05e747129a392e173e82b9048a73d05dec4b0b4a2e';

$litePath = __DIR__ . '/standings_timeline_lite.php';
$timelinePath = __DIR__ . '/standings_timeline.php';
$replacement = base64_decode('', true);

function ih(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
function row(string $label, bool $ok, string $detail=''): void {
    echo '<tr><td>'.ih($label).'</td><td class="'.($ok?'ok':'bad').'">'.($ok?'PASS':'FAIL').'</td><td>'.ih($detail).'</td></tr>';
}
function atomic_write(string $path, string $data): bool {
    $tmp=$path.'.tmp_'.bin2hex(random_bytes(4));
    if(file_put_contents($tmp,$data,LOCK_EX)===false) return false;
    if(!@rename($tmp,$path)) { @unlink($tmp); return false; }
    return true;
}

$liteExists=is_file($litePath);
$timelineExists=is_file($timelinePath);
$currentHash=$liteExists ? (string)hash_file('sha256',$litePath) : '';
$timelineBefore=$timelineExists ? (string)hash_file('sha256',$timelinePath) : '';

$baselineOk=
    $liteExists
    && $currentHash===LITE_BASE_SHA256
    && strpos((string)file_get_contents($litePath),'VERSION: v004')!==false;

$timelineOk=
    $timelineExists
    && strpos((string)file_get_contents($timelinePath),'standings_timeline.php')!==false;

$replacementOk=
    is_string($replacement)
    && hash('sha256',$replacement)===LITE_NEW_SHA256
    && strpos($replacement,'VERSION: v005')!==false
    && strpos($replacement,'margin-bottom: 43px;')!==false
    && strpos($replacement,'function stlite_display_without_seconds')!==false
    && strpos($replacement,'$asOfDisplay = stlite_display_without_seconds')!==false
    && strpos($replacement,'width: 64px;')!==false
    && strpos($replacement,'text-align: center;')!==false
    && strpos($replacement,'AUTO-SCORING – UNOFFICIAL')!==false;

$preflightOk=$baselineOk && $timelineOk && $replacementOk;
$apply=isset($_POST['apply']) && $_POST['apply']==='1';
$messages=[];$success=false;

if($apply && $preflightOk) {
    $backupDir=__DIR__.'/_migration_backups/standings_timeline_lite_v005_'.date('Ymd_His');
    $ok=is_dir($backupDir) || mkdir($backupDir,0755,true);

    if(!$ok) $messages[]='FAIL: Could not create backup directory.';

    if($ok && !copy($litePath,$backupDir.'/standings_timeline_lite.php')) {
        $ok=false;$messages[]='FAIL: Could not back up standings_timeline_lite.php v004.';
    } elseif($ok) {
        $messages[]='PASS: Backed up standings_timeline_lite.php v004.';
    }

    if($ok && !atomic_write($litePath,$replacement)) {
        $ok=false;$messages[]='FAIL: Could not install standings_timeline_lite.php v005.';
    } elseif($ok) {
        $messages[]='PASS: Installed standings_timeline_lite.php v005.';
    }

    if($ok) {
        $installed=(string)file_get_contents($litePath);
        $timelineAfter=is_file($timelinePath) ? (string)hash_file('sha256',$timelinePath) : '';
        $checks=[
            'v005 header'=>strpos($installed,'VERSION: v005')!==false,
            'final 6px vertical correction'=>strpos($installed,'margin-bottom: 43px;')!==false,
            '64px score column retained'=>strpos($installed,'width: 64px;')!==false,
            'score column centered'=>strpos($installed,'.col-score')!==false && strpos($installed,'text-align: center;')!==false,
            'no-seconds display helper'=>strpos($installed,'function stlite_display_without_seconds')!==false,
            'top as-of timestamp uses no-seconds display'=>strpos($installed,'$asOfDisplay = stlite_display_without_seconds')!==false,
            'unofficial pill retained'=>strpos($installed,'AUTO-SCORING – UNOFFICIAL')!==false,
            'replacement hash exact'=>hash_file('sha256',$litePath)===LITE_NEW_SHA256,
            'standings_timeline.php untouched'=>$timelineBefore!=='' && $timelineAfter===$timelineBefore,
        ];
        foreach($checks as $label=>$pass) {
            $messages[]=($pass?'PASS: ':'FAIL: ').$label;
            if(!$pass) $ok=false;
        }
    }

    if(!$ok && is_file($backupDir.'/standings_timeline_lite.php')) {
        if(copy($backupDir.'/standings_timeline_lite.php',$litePath)) $messages[]='ROLLBACK: Restored standings_timeline_lite.php v004.';
        else $messages[]='ROLLBACK ERROR: Could not restore standings_timeline_lite.php v004.';
    } else {
        $success=true;
    }
}
?><!doctype html>
<html lang="en">
<head>
